preConditionHook:
// EL: vol = Ticks (UpTicks + DownTicks -- NOT the `volume` alias, which is
// EL's Volume == up-ticks only; EL_Volume_Probe.txt). vol is an EL VARIABLE,
// so average(vol, n) reads its zero-filled warm-up history: mirrored here as a
// zero-initialized ring buffer, exactly as BarRangeAboveStd does.
vol = (double)ctx.Ticks[0];
if (volHistory.size() != (std::size_t)(int)lookback) {
    volHistory.assign((std::size_t)(int)lookback, 0.0);
    volCursor = 0;
}
volHistory[volCursor] = vol;
volCursor = (volCursor + 1) % volHistory.size();
avgVol = 0.0;
for (double v : volHistory) {
    avgVol += v;
}
avgVol /= (int)lookback;
